claudeSettings:
{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "command": "/usr/local/bin/pacer --account team msg hook session --planner claude-code",
            "timeout": 15,
            "type": "command",
            "statusMessage": "Checking subscription budgets"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Agent|Task|Bash",
        "hooks": [
          {
            "command": "/usr/local/bin/pacer --account team guard --planner claude-code",
            "timeout": 15,
            "type": "command"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "command": "/usr/local/bin/pacer --account team msg hook stop --planner claude-code",
            "timeout": 10,
            "type": "command"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "command": "/usr/local/bin/pacer --account team msg hook prompt --planner claude-code",
            "timeout": 10,
            "type": "command"
          }
        ]
      }
    ]
  },
  "statusLine": {
    "type": "command",
    "command": "/usr/local/bin/pacer --account team statusline"
  }
}
